  fs.mkdirSync(path.join(root, 'bin'));
  skill(path.join(root, 'ship'), 'ship', 'body\n'); fs.writeFileSync(path.join(root, 'ship', 'SKILL.md.tmpl'), '---\nname: ship\n---\n');
